SELECT * FROM COPTI 
WHERE TI001 = '24A3'
  AND TI002 IN ('20250918001',
'20250918002',
'20250918005',
'20250918006',
'20250924002',
'20250925001',
'20250927001'
)

SELECT LA004,LA005,LA006,LA007
FROM INVLA 
WHERE
LA006 = '24A3' 
AND LA007 IN (
	'20250925001',
	'20250924002',
	'20250918002',
	'20250918006',
	'20250918005',
	'20250918001',
	'20250927001'
)
GROUP BY LA004,LA005,LA006,LA007
HAVING LA006 = '24A3' 
AND LA007 IN (
	'20250925001',
	'20250924002',
	'20250918002',
	'20250918006',
	'20250918005',
	'20250918001',
	'20250927001'
)

UPDATE COPTI 
SET TI003 = TI034
WHERE TI001 = '24A3'
  AND TI002 IN ('20250918001',
'20250918002',
'20250918005',
'20250918006',
'20250924002',
'20250925001',
'20250927001'
)

UPDATE INVLA 
SET LA004 = TI003
FROM INVLA INNER JOIN COPTI ON LA006 = TI001 AND LA007 = TI002
WHERE LA006 = '24A3' 

AND LA007 IN (
	'20250925001',
	'20250924002',
	'20250918002',
	'20250918006',
	'20250918005',
	'20250918001',
	'20250927001'
)